import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Epic: Release","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/epics/release.md"},"headers":[],"relativePath":"apps/mobile/epics/release.md","filePath":"apps/mobile/epics/release.md"}'),o={name:"apps/mobile/epics/release.md"};function n(r,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="epic-release" tabindex="-1">Epic: Release <a class="header-anchor" href="#epic-release" aria-label="Permalink to &quot;Epic: Release&quot;">​</a></h1><blockquote><p>Getting the whole-instance app onto the App Store and Play Store, and — later, subject to its own rationing policy — publishing focused, single-plugin apps from the same codebase.</p></blockquote><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>📋 Planned</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Task 20.4 is this repo&#39;s primary reason to exist as a shipped product: the universal, whole-instance app, publicly released. Tasks 20.11 and 20.12 are a <strong>later, separately-gated</strong> extension — one native codebase in this repo parameterized to also build individual, single-plugin apps, per sovereign RFC 0082. Both are governed centrally; this repo carries the implementation and the store-facing artifacts.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="📋-20-4-—-store-release-setup-and-privacy-declarations" tabindex="-1">📋 20.4 — Store release setup and privacy declarations <a class="header-anchor" href="#📋-20-4-—-store-release-setup-and-privacy-declarations" aria-label="Permalink to &quot;📋 20.4 — Store release setup and privacy declarations&quot;">​</a></h4><p><strong>Goal:</strong> Prepare iOS App Store and Android Play Store release infrastructure for the universal, whole-instance shell.</p><p><strong>Deliverables:</strong></p><ul><li>iOS bundle identifier, Android application ID, icons, splash screens, app display metadata. ✅ Icons and splash generated 2026-08-07 from the <code>sovereign</code> monorepo&#39;s brand mark — see <code>resources/</code>, <code>scripts/generate-app-assets.mjs</code>; bundle ID (<code>fs.sovereign.mobile</code>) and app display name were already set from the initial scaffold.</li><li>App Store Connect and Play Console listing copy explaining the user-provided instance URL model. ✅ Drafted 2026-08-07 — see <a href="./../store-listing.html">docs/store-listing.md</a> §1.</li><li>App privacy labels / data safety declarations. ✅ Drafted 2026-08-07 — see <a href="./../store-listing.html">docs/store-listing.md</a> §2.</li><li>Signing, provisioning, and CI release documentation. <strong>Partly open</strong> — see <a href="./../store-listing.html">docs/store-listing.md</a>&#39;s &quot;Still blocked&quot; section; needs an Apple Developer Program account and Google Play Console account (human handoff) before production signing/CI can be finished.</li><li>Minimum supported iOS and Android versions selected and documented (sovereign RFC 0058 open question — resolve here). 🟡 Recommendation drafted 2026-08-07 — see <a href="./../store-listing.html">docs/store-listing.md</a> §3 (keep the existing iOS 15.0 / Android API 24 floors); needs your confirmation, not yet treated as decided.</li><li>Store-review checklist covering network access, permissions, and self-hosted instance behavior. ✅ Drafted 2026-08-07 — see <a href="./../store-listing.html">docs/store-listing.md</a> §4.</li><li>Internal test track (TestFlight / Play internal testing) verified before any public release — see <a href="./../adrs/0002-universal-one-binary-distribution.html">ADR 0002</a>. Blocked on the same account/signing prerequisites above.</li></ul><p><strong>Dependencies:</strong> Task 20.1.</p><p><strong>Technical notes:</strong></p><ul><li>Reuse the <code>sovereign-desktop</code> release&#39;s discovered iOS secret set: <code>APPLE_CERTIFICATE</code>, <code>APPLE_CERTIFICATE_PASSWORD</code>, <code>APPLE_SIGNING_IDENTITY</code>, <code>APPLE_ID</code>, <code>APPLE_PASSWORD</code>, <code>APPLE_TEAM_ID</code> — the team ID was found necessary during that release and is easy to miss.</li><li>Privacy labels / data-safety declarations must reflect reality: this shell collects nothing itself and connects only to a user-supplied instance. No telemetry by default.</li><li>Store copy must not imply Sovereign hosts user data.</li></ul><p><strong>Review checklist:</strong></p><ul><li>Store listing does not imply Sovereign hosts user data by default.</li><li>Privacy declarations match this shell&#39;s actual data collection behavior.</li><li>Required signing/provisioning secrets are documented without committing secrets.</li><li>iOS and Android release builds can be produced locally or in CI.</li><li>No telemetry is introduced by default.</li></ul><hr><h4 id="📋-20-11-—-focused-plugin-app-build-targets" tabindex="-1">📋 20.11 — Focused plugin app build targets <a class="header-anchor" href="#📋-20-11-—-focused-plugin-app-build-targets" aria-label="Permalink to &quot;📋 20.11 — Focused plugin app build targets&quot;">​</a></h4><p><strong>Goal:</strong> Publish an individual plugin as its own native app from this same codebase — one shell, parameterized, not a second project.</p><p><strong>Deliverables:</strong></p><ul><li>A declarative build-target config per app: <code>appId</code>, <code>displayName</code>, <code>defaultInstanceUrl</code>, <code>focusPlugin</code>, icon set. The whole-instance app is the target with <strong>no</strong> <code>focusPlugin</code>.</li><li>Shell sends the RFC 0080 User-Agent token extended with <code>focus=&lt;pluginId&gt;</code>.</li><li><code>server.url</code> loads the remote instance over <code>https</code> — never bundled assets behind <code>capacitor://</code>, per <a href="./../adrs/0005-server-url-not-bundled-assets.html">ADR 0005</a>.</li><li>Instance onboarding extended to validate that the <strong>target plugin</strong> is installed, enabled, and surface-compatible — not merely that the URL is a Sovereign instance.</li><li>Instance switcher re-validates the target plugin on switch.</li><li>Sign-out drives the platform&#39;s own flow so offline cache/queue clearing still fires — a native-only sign-out would leak the previous user&#39;s cached data on a shared device.</li><li>One published focused target, with the whole-instance app still building.</li></ul><p><strong>Dependencies:</strong> Task 20.10 (gate, owned centrally), Task 20.1, Task 20.2 (owned centrally), sovereign RFC 0082.</p><p><strong>Review checklist:</strong></p><ul><li>Both the whole-instance app and one focused app build from the same codebase.</li><li>The focused app loads only its plugin; out-of-focus navigation redirects to the plugin root.</li><li>Onboarding rejects an instance that lacks the target plugin, with a clear message.</li><li>Offline cold launch renders cached data (if in scope — see <a href="./../research/0003-webview-offline-behavior.html">research 0003</a>).</li><li>Sign-out clears the offline cache and queue.</li><li>No auth, role, or plugin-permission logic is duplicated in native code.</li></ul><hr><h4 id="📋-20-12-—-plugin-app-store-release-process-and-rationing-policy" tabindex="-1">📋 20.12 — Plugin app store release process and rationing policy <a class="header-anchor" href="#📋-20-12-—-plugin-app-store-release-process-and-rationing-policy" aria-label="Permalink to &quot;📋 20.12 — Plugin app store release process and rationing policy&quot;">​</a></h4><p><strong>Goal:</strong> Make publishing a focused plugin app a repeatable process with a written policy on when it&#39;s justified — the ongoing cost is per-app and permanent.</p><p><strong>Deliverables:</strong></p><ul><li>Store metadata, privacy labels, and data-safety declarations per focused target, making clear the app connects to a user-provided instance and Sovereign hosts nothing by default.</li><li>Signing identity, app identifier, and release-ownership model for multiple apps.</li><li><strong>Written rationing policy</strong> (sovereign RFC 0082 §7): the installable PWA is the default answer for any plugin wanting an app-like presence; a store-published focused app is reserved for flagship plugins where distribution or a native capability justifies the review-cycle and maintenance cost.</li><li>No telemetry by default.</li></ul><p><strong>Dependencies:</strong> Task 20.11, sovereign RFC 0082.</p><p><strong>Review checklist:</strong></p><ul><li>One focused app passes store review on both platforms.</li><li>The rationing policy is written and referenced from this epic.</li><li>Store metadata does not imply Sovereign hosts user data.</li><li>No analytics or crash reporting is enabled by default.</li></ul><h2 id="related-docs" tabindex="-1">Related docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related docs&quot;">​</a></h2><ul><li><a href="./../adrs/0002-universal-one-binary-distribution.html">ADR 0002</a>, <a href="./../adrs/0005-server-url-not-bundled-assets.html">ADR 0005</a></li><li><a href="./../research/0003-webview-offline-behavior.html">research 0003</a></li></ul>',34)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
